new='''    /// While the edge a list is resized by is being dragged, the pointer
    /// passing over the list's scrollbar lights up none of it: neither the
    /// thumb nor a button's bevel.
    #[gpui_kit::test]
    async fn nothing_in_the_scrollbar_hovers_while_an_edge_is_dragged(cx: &mut TestAppContext) {
        use crate::theme::{bevel_colors, palette};
        cx.update(gpui_kit::init);
        let split = cx.new(|_| gpui_kit::component::resizable::ResizableState::default());
        let window = cx.add_window({
            let split = split.clone();
            |window, cx| {
                let view = cx.new(|_| SplitList {
                    scroll: ScrollHandle::new(),
                    split,
                });
                Root::new(view, window, cx)
            }
        });
        let handle: gpui_kit::AnyWindowHandle = window.into();
        let (up, thumb) = cx
            .update_window(handle, |_, window, cx| {
                window.render_frame(cx);
                window.render_frame(cx);
                let track = window.find("tall-scroll-track").bounds();
                (
                    window.find("tall-scroll-up").bounds(),
                    point(track.center().x, track.top() + px(4.)),
                )
            })
            .unwrap();
        // Anything lit over the up button or the top of the thumb.
        let lit = |cx: &mut gpui_kit::VisualTestContext| {
            cx.update(|window, cx| {
                window.render_frame(cx);
                let (light, _) = bevel_colors(palette(cx));
                let hover = scroll_colors(cx.theme().is_dark()).hover;
                let scale = window.scale_factor();
                window
                    .painted_quads()
                    .into_iter()
                    .filter(|quad| {
                        let b = &quad.bounds;
                        b.origin.x.0 >= up.left().as_f32() * scale
                            && b.origin.x.0 < up.right().as_f32() * scale
                            && b.origin.y.0 >= up.top().as_f32() * scale
                            && b.origin.y.0 < (up.bottom().as_f32() + 40.) * scale
                    })
                    .filter(|quad| {
                        quad.background.as_solid() == Some(light)
                            || quad.background.as_solid() == Some(hover)
                    })
                    .count()
            })
        };
        let cx = &mut gpui_kit::VisualTestContext::from_window(handle, cx);
        // Picked up on the far side of the edge, clear of the column.
        let edge = point(up.right() + px(3.), up.bottom() + px(200.));
        cx.simulate_mouse_move(edge, None, gpui_kit::Modifiers::default());
        cx.simulate_mouse_down(edge, gpui_kit::MouseButton::Left, gpui_kit::Modifiers::default());
        for to in [up.center(), thumb] {
            cx.simulate_mouse_move(to, Some(gpui_kit::MouseButton::Left), gpui_kit::Modifiers::default());
            cx.run_until_parked();
            assert!(cx.update(|_, cx| cx.has_active_drag()), "the edge isn't being dragged");
            assert_eq!(lit(cx), 0, "the scrollbar lit up at {to:?} while the edge was dragged");
        }
        cx.simulate_mouse_up(thumb, gpui_kit::MouseButton::Left, gpui_kit::Modifiers::default());
        cx.simulate_mouse_move(up.center(), None, gpui_kit::Modifiers::default());
        cx.run_until_parked();
        assert!(lit(cx) > 0, "the button no longer lights up once the drag is over");
    }

